function cleanText(value) {
  return String(value || '').replace(/\r\n/g, '\n').trim();
}

export function inferResponseMode(userText) {
  const text=cleanText(userText);
  if(!text) return 'standard';
  const compact=/^(?:ok|go|maj|avance|continue|fini\s*\??|c['’]est\s+bon\s*\??|ça\s+marche\s*\??|ca\s+marche\s*\??|et\s+l[àa]\s*\??|maintenant\s*\??|tu\s+vois\s*\??)$/i.test(text)
    || (text.length<=90 && /\b(?:c['’]est\s+bon|fini|termin[ée]|ça\s+marche|ca\s+marche|avance|maj|statut|status|o[uù]\s+en\s+est|o[uù]\s+en\s+es)\b/i.test(text));
  if(compact) return 'compact_status';
  if(/\b(?:explique|pourquoi|comment|d[ée]taille|analyse|compare|apprends[- ]?moi|teach|explain)\b/i.test(text)) return 'explanatory';
  if(/^\s*(?:est[- ]?ce\s+que|tu\s+peux|peux[- ]?tu|as[- ]?tu|tu\s+as|est[- ]?il|est[- ]?elle)\b/i.test(text) && text.length<180) return 'direct_answer';
  return 'standard';
}

export function inferPresentationMode(userText) {
  const text=cleanText(userText);
  const responseMode=inferResponseMode(text);
  if(responseMode==='compact_status'||responseMode==='direct_answer') return 'compact';
  const structured=/\b(?:audit|rapport|roadmap|feuille\s+de\s+route|état\s+des\s+lieux|etat\s+des\s+lieux|compare|comparaison|tableau|liste|étapes?|etapes?|plan|synthèse|synthese|détaill[ée]|detaille|complet|structure|organise)\b/i.test(text)
    || text.length>=420;
  return structured?'structured':'natural';
}

// MEL-CHAT-07: a message often carries several asks ("corrige X, puis
// déploie, et dis-moi Y") and may correct an earlier answer. Both must reach
// the model explicitly, or the reply answers only the first ask.
export function extractSubRequests(userText) {
  const text=cleanText(userText);
  if(!text) return [];
  const parts=text
    .split(/(?:\n+|[;?!]\s+|\.\s+|,?\s+(?:puis|ensuite|et\s+aussi|et\s+ensuite|apr[eè]s\s+[çc]a)\s+|\s+et\s+(?=(?:dis|donne|explique|v[ée]rifie|corrige|fais|lance|montre|regarde|ajoute|supprime|d[ée]ploie|teste)\b))/i)
    .map(part=>cleanText(part).replace(/^[-*\d.)\s]+/,''))
    .filter(part=>part.length>=3);
  return parts.length>1?parts.slice(0,8):[];
}

export function latestUserCorrection(messages=[]) {
  const rows=Array.isArray(messages)?messages:[];
  for(let i=rows.length-1;i>=0;i--){
    const row=rows[i];
    if(row?.role!=='user') continue;
    const text=cleanText(typeof row.content==='string'?row.content:'');
    if(/^(?:non\b|pas\s+[çc]a|je\s+voulais\s+dire|en\s+fait\b|plut[ôo]t\b|correction\b|pardon\b|erreur\b|tu\s+t['’]es\s+tromp)|\b(?:ce\s+n['’]est\s+pas\s+ce\s+que|je\s+n['’]ai\s+pas\s+dit|corrige\s+toi)\b/i.test(text))
      return text.slice(0,400);
  }
  return null;
}

export const EVIDENCE_RECIPE='RECETTE DE PREUVE : sépare explicitement FAITS (vérifiés par un outil de cette requête), HYPOTHÈSES (déduites, non vérifiées), REFUS (ce que tu ne feras pas et pourquoi) et SOURCES CONSULTÉES (outil, fichier ou URL réellement lus). Ne présente jamais une hypothèse comme un fait.';

export function buildResponseQualityInstruction(userText, { history=[] }={}) {
  const mode=inferResponseMode(userText);
  const subRequests=extractSubRequests(userText);
  const correction=latestUserCorrection([...(Array.isArray(history)?history:[]),{role:'user',content:cleanText(userText)}]);
  const presentationMode=inferPresentationMode(userText);
  const modeRule=mode==='compact_status'
    ? 'MODE COMPACT_STATUS : réponds par le statut/conclusion dans la première phrase, puis 1 à 3 phrases utiles. Ne récite pas tout l’historique ni tous les sous-systèmes.'
    : mode==='direct_answer'
      ? 'MODE DIRECT_ANSWER : réponds oui/non/pas encore ou donne directement le fait demandé dans la première phrase, puis justifie brièvement.'
      : mode==='explanatory'
        ? 'MODE EXPLICATIF : commence par l’idée centrale, puis explique causes, mécanisme et conséquence sans digression inutile.'
        : 'MODE STANDARD : réponse naturelle, directe et proportionnée à la demande.';
  const presentationRule=presentationMode==='compact'
    ? 'PRÉSENTATION COMPACTE : réponse courte en prose naturelle; n’ajoute pas de titre, tableau ou section décorative sans nécessité.'
    : presentationMode==='structured'
      ? 'PRÉSENTATION STRUCTURÉE : utilise le Markdown lisible quand il aide réellement : titres ## pour séparer les grandes sections, **gras** pour les repères importants, listes pour les éléments parallèles, listes numérotées pour une séquence, tableaux seulement pour une vraie comparaison, > pour une citation utile et blocs de code clôturés pour du code. Garde des paragraphes courts. N’émets jamais de HTML brut.'
      : 'PRÉSENTATION NATURELLE : privilégie des paragraphes courts; utilise une liste ou du gras seulement si cela améliore nettement la lecture. Ne force ni titre ni tableau. N’émets jamais de HTML brut.';
  return [
    '[MEL_RESPONSE_QUALITY]',
    `mode=${mode}`,
    `presentation=${presentationMode}`,
    modeRule,
    presentationRule,
    'La première phrase doit répondre à la demande actuelle, pas commenter la méthode de réponse.',
    'VERROU DE SUJET : reste sur le sujet et le niveau demandés dans le dernier message. Ne saute pas vers un ancien chantier, un autre module, une autre branche ou une autre interprétation simplement parce qu’ils existent dans l’historique.',
    'Si le message est elliptique (ex. « continue », « fais-le », « et maintenant ? »), résous d’abord son référent depuis les échanges récents de la même conversation; n’utilise une mémoire plus ancienne que si le référent récent ne suffit pas.',
    'Si plusieurs interprétations restent réellement possibles et qu’elles mèneraient à des actions différentes, demande une clarification courte au lieu de choisir arbitrairement un autre plan.',
    'N’utilise pas « en tant qu’IA », « je dois préciser » ou un préambule défensif quand une réponse factuelle directe est possible.',
    'Ne récite pas l’architecture interne, les garde-fous ou les limitations générales sauf si Adrien les demande ou si une limite change réellement la réponse.',
    'Quand une preuve runtime existe, cite le fait précis (statut, branche, SHA, job, erreur) plutôt qu’une formulation vague.',
    'Distingue : vérifié maintenant / connu par mémoire / non observable. Ne transforme jamais « non observé » en « impossible ».',
    'Si une action est déjà exécutée par un outil, parle au présent ou au passé factuel; ne dis pas « je vais le faire ».',
    'Si une action est seulement mise en file ou en cours, ne dis jamais « c’est fait », « terminé » ou « déployé ».',
    'Garde un ton naturel, calme et conversationnel; évite les répétitions et les formulations mécaniques.',
    ...(subRequests.length?['SOUS-DEMANDES À TRAITER TOUTES, dans l’ordre : '+subRequests.map((r,i)=>(i+1)+') '+r).join(' ')+'. N’en omets aucune; si une ne peut pas être faite, dis laquelle et pourquoi.']:[]),
    ...(correction?['DERNIÈRE CORRECTION D’ADRIEN (prioritaire sur toute réponse antérieure) : « '+correction+' ».']:[]),
    EVIDENCE_RECIPE,
    '[/MEL_RESPONSE_QUALITY]'
  ].join(' ');
}

function asksCodeAccess(userText) {
  const text=cleanText(userText);
  return /\b(?:acc[eè]s|acc[eè]der|voir|lire|inspecter)\b/i.test(text)
    && /\b(?:code|source|repo|repository|d[ée]p[ôo]t|github)\b/i.test(text);
}

function deniesCodeAccess(text) {
  return /\b(?:je\s+n['’]?ai\s+pas\s+acc[eè]s|je\s+ne\s+peux\s+pas\s+(?:acc[eè]der|voir|lire|inspecter)|je\s+ne\s+vois\s+pas\s+(?:mon|le)\s+(?:code|d[ée]p[ôo]t|repo))\b/i.test(text);
}

function claimsCompletion(text) {
  return /\b(?:c['’]est\s+fait|c['’]est\s+termin[ée]|termin[ée]|fini|d[ée]ploy[ée]\s+en\s+prod(?:uction)?|en\s+production)\b/i.test(text);
}

function successfulCodeEvidence(toolResults=[]) {
  const rows=Array.isArray(toolResults)?toolResults:[];
  for(let i=rows.length-1;i>=0;i--){
    const row=rows[i];
    if(row?.status!=='SUCCEEDED') continue;
    if(!['code.read','code.search','code.integrity'].includes(String(row?.capability||''))) continue;
    const r=row.result||{};
    return {
      capability:String(row.capability),
      path:r.path||r.file||null,
      branch:r.branch||r.self_code?.branch||null,
      head:r.head||r.self_code?.commit||null,
    };
  }
  return null;
}

function latestFailure(toolResults=[]) {
  const rows=Array.isArray(toolResults)?toolResults:[];
  for(let i=rows.length-1;i>=0;i--){
    const row=rows[i];
    if(row?.status==='FAILED') return {capability:String(row.capability||'outil'),error:String(row.error||'CAPABILITY_FAILED')};
  }
  return null;
}

function successfulKnowledgeEvidence(toolResults=[]){
  const rows=Array.isArray(toolResults)?toolResults:[];
  for(let i=rows.length-1;i>=0;i--){
    const row=rows[i];
    if(row?.status!=='SUCCEEDED') continue;
    const id=String(row?.capability||'');
    if(!id.startsWith('knowledge.')) continue;
    return {capability:id,result:row.result||{}};
  }
  return null;
}

function deniesKnowledgeAction(text){
  return /\b(?:je\s+ne\s+peux\s+pas|je\s+n['’]?ai\s+pas\s+la\s+possibilit[ée]|je\s+n['’]?ai\s+pas\s+acc[eè]s)\b[^.!?]{0,140}(?:recherch\w*|internet|web|fichiers?|dossiers?|m[ée]mor\w*|sauvegard\w*|class\w*|retrouv\w*|v[ée]rifi\w*)/i.test(String(text||''));
}
function knowledgeEvidenceFallback(evidence){
  if(!evidence)return '';
  const id=evidence.capability,r=evidence.result||{};
  if(id==='knowledge.research'){
    const bits=['J’ai effectué la recherche'];
    if(r.verification?.status) bits.push('statut de vérification '+r.verification.status);
    if(Number.isFinite(Number(r.verification?.source_count))) bits.push(String(r.verification.source_count)+' source(s)');
    if(r.artifact?.filename) bits.push('fichier '+r.artifact.filename);
    if(r.artifact?.storage) bits.push('stockage '+r.artifact.storage);
    if(r.memory?.stored===true) bits.push('référence mémorisée');
    const summary=String(r.research?.summary||'').trim();
    return bits.join(' ; ')+'.'+(summary?' '+summary:'');
  }
  if(id==='knowledge.search'){
    const rows=Array.isArray(r.artifacts)?r.artifacts:[];
    const names=rows.slice(0,5).map(x=>x.filename||x.title||x.id).filter(Boolean);
    return 'J’ai recherché dans mes dossiers durables : '+Number(r.count||rows.length)+' résultat(s)'+(names.length?' — '+names.join(', '):'')+'.';
  }
  if(id==='knowledge.file.read'){
    const a=r.artifact||{};
    return 'J’ai relu le fichier '+String(a.filename||a.id||'demandé')+' ; intégrité SHA-256 '+(a.integrity_ok===true?'valide':'non confirmée')+'.';
  }
  if(id==='knowledge.file.create'){
    const a=r.artifact||{};
    return 'J’ai créé le fichier '+String(a.filename||a.id||'demandé')+(a.storage?' ('+a.storage+')':'')+'.';
  }
  return '';
}

function stripMetaPreamble(text) {
  return cleanText(text)
    .replace(/^En\s+tant\s+qu['’](?:IA|intelligence\s+artificielle)[^.!?]*[.!?]\s*/i,'')
    .replace(/^Je\s+dois\s+pr[ée]ciser\s+que\s+/i,'');
}

// An LLM can print a plausible capability invocation or JSON success object.
// Only CapabilityBus tool_results from the current request are execution receipts.
// This guard must run on the model output, not on quoted user input.
function hasExecutedD1Receipt(rows, capability) {
  return (Array.isArray(rows) ? rows : []).some(row => {
    if (row?.capability !== capability || row?.status !== 'SUCCEEDED') return false;
    const result = row.result || {};
    if (capability === 'd1.write') {
      return result.approved === true
        && Number(result.changes) > 0
        && ['insert', 'update', 'delete'].includes(String(result.operation || ''));
    }
    return capability === 'd1.read' && Array.isArray(result.rows);
  });
}

function guardClaimedD1Execution(text, toolResults) {
  const reply = cleanText(text);
  const mentionsWrite = /\bd1\.write\b/i.test(reply);
  const mentionsRead = /\bd1\.(?:read|get)\b/i.test(reply);
  const mentionsApprovalFlag = /\bmax_auto_approval\b/i.test(reply);
  if (!mentionsWrite && !mentionsRead && !mentionsApprovalFlag) return reply;

  const reportsExecution = /(?:action\s+ex[ée]cut[ée]e|r[ée]sultat\s+obtenu|j['’]ai\s+(?:interrog[ée]|ex[ée]cut[ée]|lanc[ée]|cr[ée][ée]?|ajout[ée]|modifi[ée]|enregistr[ée]|mis\s+[àa]\s+jour)|(?:configuration|cl[ée])\s+(?:a\s+[ée]t[ée]\s+)?(?:mise?\s+[àa]\s+jour|ajout[ée]e?|activ[ée]e?)\s+(?:avec\s+succ[èe]s)?|["']?success["']?\s*:\s*true)/i.test(reply);
  const unverifiedWrite = (mentionsWrite || mentionsApprovalFlag)
    && reportsExecution && !hasExecutedD1Receipt(toolResults, 'd1.write');
  // d1.get is not a registered capability. A d1.read receipt cannot verify a
  // differently named operation asserted by the model.
  const unverifiedRead = mentionsRead && reportsExecution
    && (!hasExecutedD1Receipt(toolResults, 'd1.read') || /\bd1\.get\b/i.test(reply));
  // A D1 config row alone cannot grant GitHub, Council, or release authority.
  const claimsApprovalAuthority = mentionsApprovalFlag
    && /(?:max\b[^.!?\n]{0,130}(?:approuv|fusionn|d[ée]ploi)|(?:approuv|fusionn|d[ée]ploi)[^.!?\n]{0,130}automatique|autorisation\s+permanente\s+activ[ée]e?)/i.test(reply);

  if (!unverifiedWrite && !unverifiedRead && !claimsApprovalAuthority) return reply;
  const executed = (Array.isArray(toolResults) ? toolResults : [])
    .filter(row => /^d1\.(?:write|read)$/.test(String(row?.capability || '')))
    .map(row => String(row.capability) + ': ' + String(row.status || 'UNKNOWN'))
    .slice(0, 4);
  return [
    "Je ne peux pas confirmer l'action D1 annoncée dans cette réponse : elle n'est pas étayée par un résultat d'outil authentifié de cette requête, ou son effet sur les autorisations MAX n'est pas vérifié.",
    executed.length ? 'Résultats D1 réellement observés : ' + executed.join(' ; ') + '.' : 'Aucun reçu d’exécution D1 correspondant n’est disponible.',
    "La clé max_auto_approval, même présente dans D1, ne constitue pas une autorisation technique de fusionner des PR ou de déployer. Les contrôles CI, Council et la validation du SHA restent obligatoires."
  ].join(' ');
}

export function finalizeEvidenceAlignedResponse({
  text,
  userText,
  codeAccess,
  toolResults=[],
  developmentQueued=null,
  requireD1ExecutionReceipts=false,
}={}) {
  let out=stripMetaPreamble(text);
  const codeEvidence=successfulCodeEvidence(toolResults);

  if(asksCodeAccess(userText) && codeAccess?.available===true && deniesCodeAccess(out)){
    const proof=[];
    if(codeEvidence?.path) proof.push(`fichier ${codeEvidence.path}`);
    if(codeEvidence?.branch) proof.push(`branche ${codeEvidence.branch}`);
    if(codeEvidence?.head) proof.push(`SHA ${String(codeEvidence.head).slice(0,8)}`);
    out=codeEvidence
      ? `Oui, j’ai accès à mon dépôt/code MEL via mes capacités code${proof.length ? ` ; cette requête a vérifié ${proof.join(', ')}` : ''}. Une lecture précise n’est affirmée que lorsqu’un outil code l’a réellement exécutée sur la cible demandée.`
      : 'La capacité d’accès au code est déclarée disponible, mais aucune exécution réussie de lecture du dépôt n’est prouvée pour cette requête. Je ne peux donc pas certifier une lecture effective maintenant.';
  }

  if(developmentQueued && claimsCompletion(out)){
    const job=String(developmentQueued.job_id||'').trim();
    const status=String(developmentQueued.status||'QUEUED').trim();
    out=`Le développement est enregistré${job?` sous le job ${job}`:''} (statut ${status}). Il n’est pas encore prouvé terminé ni déployé : je le considérerai terminé seulement après une preuve de completion/CI correspondant au niveau annoncé.`;
  }

  // A model-generated claim is not a GitHub/Cloudflare receipt. Chat may
  // describe a completed PR or deployment only when this turn has verifiable
  // evidence; a queued evolution job and generic tool success do not qualify.
  const claimsRepoDelivery = /(?:\bPR\s*#?\d+\b[^\n.]{0,100}(?:fusionn[ée]e?|d[ée]ploy[ée]e?|cr[ée][ée]e?)|\b(?:PR|pull request)\b[^\n.]{0,100}(?:fusionn[ée]e?|d[ée]ploy[ée]e?)|\bd[ée]ploiement\b[^\n.]{0,80}(?:r[ée]ussi|effectu[ée]|termin[ée]))/i.test(out);
  const hasReleaseReceipt = (Array.isArray(toolResults) ? toolResults : []).some(row => {
    if (row?.status !== 'SUCCEEDED') return false;
    const r = row.result || {};
    if (/github|pull.request|cloudflare|deployment/i.test(String(row.capability || '')))
      return Boolean(r.html_url || r.url || r.merge_commit_sha || r.deployment_id || r.deploy_id);
    return false;
  });
  if (claimsRepoDelivery && !hasReleaseReceipt) {
    out = 'Je ne dispose pas, dans les résultats vérifiés de cette requête, d’un reçu GitHub ou Cloudflare attestant la création, la fusion ou le déploiement annoncé. Je ne peux donc pas présenter cette opération comme réussie. Consulte les journaux persistants et les outils autorisés pour obtenir une preuve réelle.';
  }

  const beforeD1Guard = out;
  if (requireD1ExecutionReceipts === true) out = guardClaimedD1Execution(out, toolResults);
  const d1EvidenceCorrectionApplied = out !== beforeD1Guard;

  const knowledgeEvidence=successfulKnowledgeEvidence(toolResults);
  if(knowledgeEvidence && deniesKnowledgeAction(out)){
    const replacement=knowledgeEvidenceFallback(knowledgeEvidence);
    if(replacement) out=replacement;
  }

  const failure=latestFailure(toolResults);
  if(failure && !d1EvidenceCorrectionApplied && /\b(?:je\s+n['’]?ai\s+pas\s+acc[eè]s|je\s+ne\s+peux\s+pas)\b/i.test(out)){
    out=`L’opération ${failure.capability} a échoué cette fois (${failure.error}). Cet échec ponctuel ne prouve pas une incapacité générale ; les autres capacités restent décrites par leur état runtime courant.`;
  }

  return cleanText(out);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {
  inferResponseMode,
  inferPresentationMode,
  buildResponseQualityInstruction,
  finalizeEvidenceAlignedResponse,
} from '../src/api/response-quality.js';

test('short progress questions get compact status mode', () => {
  for(const text of ["c'est bon ?", 'fini ?', 'maj', 'avance', 'ça marche ?']){
    assert.equal(inferResponseMode(text),'compact_status',text);
  }
  assert.equal(inferResponseMode('explique-moi pourquoi cette réponse était incohérente'),'explanatory');
});

test('quality instruction forces answer-first evidence-oriented communication', () => {
  const prompt=buildResponseQualityInstruction("c'est bon ?");
  assert.match(prompt,/MODE COMPACT_STATUS/);
  assert.match(prompt,/première phrase/i);
  assert.match(prompt,/vérifié maintenant/i);
  assert.match(prompt,/ne dis jamais « c’est fait »/i);
  assert.match(prompt,/VERROU DE SUJET/);
  assert.match(prompt,/échanges récents de la même conversation/i);
});


test('presentation mode stays compact for short answers and becomes structured for reports', () => {
  assert.equal(inferPresentationMode("c'est bon ?"), 'compact');
  assert.equal(inferPresentationMode('oui ou non ?'), 'natural');
  assert.equal(inferPresentationMode('fais un audit complet et une roadmap des étapes restantes'), 'structured');
  assert.equal(inferPresentationMode('compare ces options dans un tableau'), 'structured');
});

test('quality instruction teaches structured Markdown without raw HTML', () => {
  const structured=buildResponseQualityInstruction('fais un audit complet avec les étapes et un tableau comparatif');
  assert.match(structured,/presentation=structured/);
  assert.match(structured,/titres ##/i);
  assert.match(structured,/tableaux seulement/i);
  assert.match(structured,/N’émets jamais de HTML brut/i);

  const compact=buildResponseQualityInstruction('maj');
  assert.match(compact,/presentation=compact/);
  assert.match(compact,/n’ajoute pas de titre, tableau ou section décorative/i);
});

test('code-access contradiction is repaired when runtime proves access', () => {
  const out=finalizeEvidenceAlignedResponse({
    text:"Je n'ai pas accès à mon code source.",
    userText:"tu as accès à ton code ?",
    codeAccess:{available:true},
    toolResults:[{capability:'code.integrity',status:'SUCCEEDED',result:{branch:'candidate/mel-clean-autonomy',head:'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'}}],
  });
  assert.match(out,/Oui, j’ai accès à mon dépôt\/code MEL/i);
  assert.match(out,/branche candidate\/mel-clean-autonomy/i);
  assert.doesNotMatch(out,/je n['’]ai pas accès/i);
});

test('queued development cannot be described as already completed', () => {
  const out=finalizeEvidenceAlignedResponse({
    text:"C'est fait et déployé en production.",
    userText:'améliore tes réponses',
    codeAccess:{available:true},
    developmentQueued:{job_id:'job-42',status:'RUNNING'},
  });
  assert.match(out,/job job-42/);
  assert.match(out,/statut RUNNING/);
  assert.match(out,/pas encore prouvé terminé ni déployé/i);
});

test('punctual tool failure is not converted into global incapacity', () => {
  const out=finalizeEvidenceAlignedResponse({
    text:"Je ne peux pas accéder à cela.",
    userText:'lis ce fichier',
    codeAccess:{available:true},
    toolResults:[{capability:'code.read',status:'FAILED',error:'UPSTREAM_TIMEOUT'}],
  });
  assert.match(out,/code\.read a échoué cette fois/i);
  assert.match(out,/UPSTREAM_TIMEOUT/);
  assert.match(out,/ne prouve pas une incapacité générale/i);
});

test('meta AI preambles are removed from otherwise useful answers', () => {
  const out=finalizeEvidenceAlignedResponse({
    text:"En tant qu'intelligence artificielle, je peux t'expliquer le mécanisme. Voici le point essentiel.",
    userText:'explique',
  });
  assert.doesNotMatch(out,/^En tant qu/i);
  assert.match(out,/Voici le point essentiel/);
});


test('successful knowledge research prevents a false global incapacity answer', () => {
  const out=finalizeEvidenceAlignedResponse({
    text:"Je ne peux pas faire de recherche sur internet ni créer de fichier.",
    userText:"cherche ceci et enregistre-le",
    toolResults:[{capability:'knowledge.research',status:'SUCCEEDED',result:{
      verification:{status:'VERIFIED_MULTI_SOURCE',source_count:2},
      artifact:{filename:'dossier.md',storage:'D1+R2'},
      memory:{stored:true},
      research:{summary:'Found 2 relevant sources.'},
    }}],
  });
  assert.match(out,/J’ai effectué la recherche/i);
  assert.match(out,/dossier\.md/);
  assert.match(out,/référence mémorisée/i);
  assert.doesNotMatch(out,/je ne peux pas/i);
});

test('code capability presence alone does not prove that code was read', () => {
  const out=finalizeEvidenceAlignedResponse({
    text:"Je n'ai pas accès à mon code source.",
    userText:"tu peux lire ton code source ?",
